<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\{AdPlacement,SponsorshipPackage};use Illuminate\Http\Request;use Illuminate\Support\Str;use Inertia\Inertia;
class SponsorshipPackageController extends Controller{public function index(){return Inertia::render('Admin/Sponsorship/Packages/Index',['packages'=>SponsorshipPackage::with('placements')->orderBy('name')->get()]);}public function create(){return Inertia::render('Admin/Sponsorship/Packages/Form',['package'=>null,'placements'=>AdPlacement::where('is_active',true)->orderBy('name')->get()]);}public function store(Request $r){$d=$this->data($r);$p=SponsorshipPackage::create(array_merge($d,['uuid'=>(string)Str::uuid()]));$p->placements()->sync($this->pivot($r));return to_route('admin.sponsorship-packages.index')->with('success','Sponsorship package created.');}public function edit(SponsorshipPackage $sponsorshipPackage){return Inertia::render('Admin/Sponsorship/Packages/Form',['package'=>$sponsorshipPackage->load('placements'),'placements'=>AdPlacement::orderBy('name')->get()]);}public function update(Request $r,SponsorshipPackage $sponsorshipPackage){$sponsorshipPackage->update($this->data($r));$sponsorshipPackage->placements()->sync($this->pivot($r));return to_route('admin.sponsorship-packages.index')->with('success','Sponsorship package updated.');}public function destroy(SponsorshipPackage $sponsorshipPackage){abort_if($sponsorshipPackage->placements()->exists()&&$sponsorshipPackage->is_active,422);$sponsorshipPackage->delete();return back()->with('success','Package deleted.');}private function data(Request $r):array{return $r->validate(['name'=>'required|string|max:255','code'=>'required|string|max:100|unique:sponsorship_packages,code,'.($r->route('sponsorship_package')?->id??'NULL'),'description'=>'nullable|string','duration_days'=>'required|integer|min:1','base_price_cents'=>'required|integer|min:0','package_price_cents'=>'required|integer|min:0','impression_goal'=>'nullable|integer|min:0','click_goal'=>'nullable|integer|min:0','included_creatives'=>'required|integer|min:1','billing_terms'=>'required|string|max:255','is_active'=>'boolean','internal_notes'=>'nullable|string']);}private function pivot(Request $r):array{$out=[];foreach($r->input('placement_ids',[]) as $id)$out[$id]=['quantity'=>1,'priority'=>50];return $out;}}
